import { useState, useEffect } from 'react';
import API from '../../api/axios';
import toast from 'react-hot-toast';
import CustomerSearch from '../../components/CustomerSearch';

export default function AdminCardRegister() {
  const [rfidUid, setRfidUid] = useState('');
  const [users, setUsers] = useState([]);
  const [selectedUserId, setSelectedUserId] = useState('');
  const [loading, setLoading] = useState(false);

  // Dynamically pull the company ID from the logged-in admin's session
  const adminInfo = JSON.parse(localStorage.getItem('adminInfo'));
  const companyId = adminInfo?._id || process.env.REACT_APP_COMPANY_ID;

  useEffect(() => {
    if (companyId) {
      API.get(`/users/company/${companyId}`)
        .then(res => setUsers(res.data))
        .catch((err) => {
          console.error("API Fetch Error:", err);
          toast.error('Failed to load customer database');
        });
    }
  }, [companyId]);

  const handleLinkCard = async (e) => {
    e.preventDefault();
    if (!selectedUserId) return toast.error("Please select a customer from the search dropdown.");
    
    setLoading(true);

    try {
      const { data } = await API.post('/cards/register', {
        cardUID: rfidUid,
        companyId,
        userId: selectedUserId
      });
      toast.success(data.message);
      setRfidUid('');
      setSelectedUserId('');
    } catch (error) {
      toast.error(error.response?.data?.message || 'Card linking failed');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="w-full max-w-md p-8 bg-white rounded-2xl shadow-lg border border-gray-100 space-y-6 mx-auto mt-10">
      <div>
        <h2 className="text-2xl font-bold text-gray-900">Link RFID Card</h2>
        <p className="text-sm text-gray-500">Assign a physical card tag to a registered customer account.</p>
      </div>

      <form onSubmit={handleLinkCard} className="space-y-4">
        <div>
          <label className="block text-xs font-semibold uppercase tracking-wider text-gray-600 mb-1">Card UID (from ESP32)</label>
          <input
            type="text"
            value={rfidUid}
            onChange={(e) => setRfidUid(e.target.value)}
            required
            placeholder="e.g. 4FFE207B"
            className="w-full px-4 py-2.5 bg-gray-50 border border-gray-300 rounded-lg text-gray-800 focus:outline-none focus:ring-2 focus:ring-indigo-500 font-mono uppercase"
          />
        </div>

        <div>
          <label className="block text-xs font-semibold uppercase tracking-wider text-gray-600 mb-1">Customer Search</label>
          <CustomerSearch 
            users={users} 
            selectedUserId={selectedUserId} 
            onSelect={setSelectedUserId} 
          />
        </div>

        <button
          type="submit"
          disabled={loading}
          className="w-full py-3 px-4 bg-indigo-600 hover:bg-indigo-700 text-white font-medium rounded-lg transition duration-200 disabled:opacity-50 shadow-sm mt-2"
        >
          {loading ? 'Linking Card...' : 'Save Card Link'}
        </button>
      </form>
    </div>
  );
}
